resolveIncluded := func(dst map[string]interface{}) {
	includeFields, ok := onApprove["include_fields"].([]interface{})
	if !ok { return }
	for _, f := range includeFields {
		fieldName, ok := f.(string)
		if !ok { continue }
		if v, present := spec[fieldName]; present && v != nil { dst[fieldName] = v; continue }
		if v, present := approvedMap[fieldName]; present { dst[fieldName] = v }
	}
}

fanOutFrom, _ := onApprove["fan_out_from"].(string)          // 'edits', from migration 750
fanOutDefaults, _ := onApprove["defaults"].(map[string]interface{})
raw, present := approvedMap[fanOutFrom]                       // <- where `elements` comes from
if present { if arr, isArr := raw.([]interface{}); isArr { elements, fannedOut = arr, true
    if len(arr) == 0 { fanOutNote = "fan_out_from %q is an EMPTY array — nothing was filed" } } }
// missing key / wrong type -> fannedOut=false -> single item AND a fan_out_note. Never silent.
if fannedOut { for i, raw := range elements {
	followSpec := map[string]interface{}{}
	for k, v := range fanOutDefaults { followSpec[k] = v }
	resolveIncluded(followSpec)
	for k, v := range el { followSpec[k] = v }
	applyIdentity(followSpec)   // provenance LAST; not overwritable by an element
	createFollowOn(followSpec, fmt.Sprintf(" (%d of %d)", i+1, len(elements)))
} } else { /* exactly today's single item, carrying approved_data */ }
// batch_id: one uuid minted per approval, shared by all N children —
// site_work_items.batch_id, the platform's existing grouping convention.
// createFollowOn's insert failure -> skippedEdits{label, reason}, never a silent shrink.

SELECT pc.updated_at > $3        -- $3 = the review item's created_at
  FROM page_components pc JOIN pages p ON p.id = pc.page_id
 WHERE pc.id = $1::uuid AND p.site_id = $2
// sql.ErrNoRows -> address GONE -> skippedEdits, REFUSED (answerable)
// true          -> MIGHT have moved -> staleWarnings{filed:true, warning:'...not proof...'}, FILED
//                  (updated_at cannot separate a content edit from a status-only write)

followOnIDs := []string{}   // EXPLICITLY empty, never nil: a nil slice marshals to `null`
followOnDetail := map[string]interface{}{"follow_on_items": followOnIDs}
if len(skippedEdits)  > 0 { followOnDetail["skipped_edits"]  = skippedEdits }
if len(staleWarnings) > 0 { followOnDetail["stale_warnings"] = staleWarnings }
if fanOutNote != ""       { followOnDetail["fan_out_note"]   = fanOutNote }
